pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRate, uint128 vBase, uint128 vNft) public {
        bytes32 merkleRoot = bytes32(0);
        address baseToken = address(0);
        address nft = address(0x1234);
        uint56 changeFee = 0;
        bool useStolen = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (feeRate > 5000) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}
